CREATE PROCEDURE migrate_customer_ids()
LANGUAGE plpgsql
AS $$
DECLARE
  batch_size int := 1000;
  processed int;
BEGIN
  LOOP
    WITH batch AS (
      DELETE FROM legacy_customer_map
      WHERE order_id IN (SELECT order_id FROM legacy_customer_map LIMIT batch_size)
      RETURNING order_id, customer_id
    )
    UPDATE orders o
    SET customer_id = b.customer_id
    FROM batch b
    WHERE o.id = b.order_id;
    GET DIAGNOSTICS processed = ROW_COUNT;
    IF processed = 0 THEN
      EXIT;
    END IF;
    COMMIT;
  END LOOP;
END;
$$;

CALL migrate_customer_ids();

DROP PROCEDURE migrate_customer_ids();

ALTER TABLE orders ALTER COLUMN customer_id SET NOT NULL;

ALTER TABLE orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id);
